/// Extension methods for a mutable `Any` trait object
pub trait AnyMutExt<'a> {
    /// Returns some mutable reference to the boxed value if it is of type `T`, or
    /// `None` if it isn't.
    fn as_mut<T: 'static>(self) -> Option<&'a mut T>;
}

impl<'a> AnyMutExt<'a> for &'a mut Any {
    #[inline]
    fn as_mut<T: 'static>(self) -> Option<&'a mut T> {
        if self.is::<T>() {
            unsafe {
                // Get the raw representation of the trait object
                let to: TraitObject = transmute_copy(&self);

                // Extract the data pointer
                Some(transmute(to.data))
            }
        } else {
            None
        }
    }
}

/// Extension methods for `Box<Any>`
pub trait AnyBoxExt {
    /// Unwraps the `Box<T>` from the trait object if it is of type `T`, or
    /// returns `None` if it isn't.
    fn move_out<T: 'static>(self: Box<Self>) -> Option<Box<T>>;
}

impl<T: 'static> AnyBoxExt for Box

