rust
fn convert_rgb_to_hsv(rgb: Rgb) -> Hsv {
    let r = rgb.red as f32 / 255.0;
    let g = rgb.green as f32 / 255.0;
    let b = rgb.blue as f32 / 255.0;

    let max = r.max(g).max(b);
    let min = r.min(g).min(b);
    let delta = max - min;

    let mut hue = 0.0;
    if delta != 0.0 {
        if max == r {
            hue = (g - b) / delta;
        } else if max == g {
            hue = 2.0 + (b - r) / delta;
        } else {
            hue = 4.0 + (r - g) / delta;
        }
        hue = (hue * 60.0).rem_euclid(360.0);
    }

    let saturation = if max == 0.0 { 0.0 } else { delta / max };
    let value = max;

    Hsv {
        hue,
        saturation,
        value,
    }
}

