require_capability!("test_ptrace_cont", CAP_SYS_PTRACE);
    let err = ptrace::cont(getpid(), None).unwrap_err();
    assert!(err == Errno::EPERM || err == Errno::EINVAL || err == Errno::ENOSYS);
}

