/// Encrypts the given message and returns the ciphertext along with the authentication tag.
    pub fn encrypt(&self, message: &[u8]) -> (Vec<u8>, [u8; AUTH_TAG_BYTES]) {
        let mut ciphertext = vec![0u8; message.len()];
        chacha20::stream(&self.encryption_key, &self.nonce, message, &mut ciphertext);

        let auth_tag = self.plain_auth_tag(&ciphertext);
        (ciphertext, auth_tag)
