    /// Decrypts the given ciphertext and verifies the authentication tag. Returns the original message if verification is successful.
    pub fn decrypt(&self, ciphertext: &[u8], auth_tag: &[u8]) -> Option<Vec<u8>> {
        if self.verify_auth(auth_tag, ciphertext) {
            let mut message = vec![0u8; ciphertext.len()];
            chacha20::stream(&self.encryption_key, &self.nonce, ciphertext, &mut message);
            Some(message)
        } else {
            None
        }
    }
