pub struct ClientHandler {
    clients: Arc<Mutex<RoutingTable<ClientId, ClientHandle>>>,
    receiver: UnboundedReceiver<Event>,
}

impl ClientHandler {
    pub fn new(clients: Arc<Mutex<RoutingTable<ClientId, ClientHandle>>>, receiver: UnboundedReceiver<Event>) -> Self {
        ClientHandler { clients, receiver }
    }

    pub fn handle_events(&mut self) {
        while let Ok(event) = self.receiver.try_recv() {
            match event.content {
                EventContent::Connected => {
                    // Handle new client connection
                    let client_id = event.client_id;
                    let handle = ClientHandle {
                        client_id,
                        ctrl_chan: unbounded().0,
                        request_counter: 0,
                    };
                    self.clients.lock().unwrap().insert(client_id, handle);
                },
                EventContent::Disconnected => {
                    // Handle client disconnection
                    self.clients.lock().unwrap().remove(&event.client_id);
                },
                EventContent::Message { message_id, data } => {
