            let client_id = self.client_id;
            let request_id = RequestId { client_id, request_num };

            self.dispatch_event(EventContent::Response {
                request_id,
                value: Err(ResponseError::Timeout),
            });
        }
    }

    fn handle_packet(&mut self, data: Vec<u8>) {
