rust
pub fn load_document(&self, url: Url, load_type: LoadType, sender: Sender<MainThreadScriptMsg>) {
    let resource_task = ResourceTask::new(url.clone(), load_type.clone());
    let pending_load = PendingAsyncLoad::new(resource_task, sender.clone());

    // Register the pending load
    self.pending_loads.insert(url.clone(), pending_load);

    // Start loading the resource
    load_whole_resource(url, move |result| {
        match result {
            Ok(data) => {
                // Handle the loaded data
                let msg = MainThreadScriptMsg::LoadComplete(url, data);
                sender.send(msg).unwrap();
            },
            Err(err) => {
                // Handle the error
                let msg = MainThreadScriptMsg::LoadError(url, err);
                sender.send(msg).unwrap();
            }
        }

        // Remove the load from pending loads
        self.pending_loads.remove(&url);
    });
}

