pub fn load_document(url: Url, target: Arc<dyn AsyncResponseTarget>, sender: Sender<MainThreadScriptMsg>) -> PendingAsyncLoad {
    let load_type = LoadType::PageSource(url.clone());

    let resource_task = ResourceTask::new(load_type.clone(), target.clone(), |response| {
        match response {
            Ok(data) => {
                // Process the successful response
                sender.send(MainThreadScriptMsg::LoadComplete(url, data)).unwrap();
            },
            Err(e) => {
                // Handle error case
                sender.send(MainThreadScriptMsg::LoadError(url, e)).unwrap();
            }
        }
    });

    load_whole_resource(url, resource_task)
}

