            normalShader.setMat4(c_str!("model"), &model);

            nanoSuit.Draw(&normalShader);
        }

        // glfw: swap buffers and poll IO events (keys pressed/released, mouse moved etc.)
        // -------------------------------------------------------------------------------
        window.swap_buffers();
        glfw.poll_events();
    }
}

