pub fn parse(input: &str) -> Result<AST, String> {
    let tokenizer = TOKENIZER.build();
    let tokens = tokenizer.tokenize(input).map_err(|e| e.to_string())?;

    let mut parser = RULE.build();
    parser.parse(tokens).map_err(|e| e.to_string())
}

