    SEMICOLON,
    LPAREN,
    RPAREN,
    LBRACE,
    RBRACE,
    LBRACKET,
    RBRACKET,
    IDENTIFIER,
    STRING_LITERAL,
    NUMBER_LITERAL,
    BOOLEAN_LITERAL,
};

pub fn parse_source(source: &str) -> Result<AST, String> {
    let tokenizer = TOKENIZER.tokenize(source)
        .map_err(|e| format!("Tokenization error: {}", e))?;

    let mut parser = fall_parse::Parser::new();
    let ast = parser.parse(&tokenizer)
        .map_err(|e| format!("Parsing error: {}", e))?;

    Ok(ast)
}

