#[inline(always)]
fn load_bytes(ptr: *const Bytes) -> Bytes {
    unsafe { *ptr }
}

#[test]
fn test_load_bytes() {
    let bytes = Bytes { a: 1, b: 2, c: 3 };
    let ptr: *const Bytes = &bytes;

    let loaded = load_bytes(ptr);
    assert_eq!(loaded.a, 1);
    assert_eq!(loaded.b, 2);
    assert_eq!(loaded.c, 3);
}

