    pub fn find<P, C>(&self, target: P, cwd: P, checker: &C) -> Option<PathBuf>
    where
        P: AsRef<Path>,
        C: Checker,
    {
        let target_path = target.as_ref();
        let cwd_path = cwd.as_ref();

        if target_path.has_separator() {
            let absolute_path = target_path.to_absolute(cwd_path);
            if checker.is_valid(&absolute_path) {
                return Some(absolute_path);
            }
        } else {
            for entry in env::var_os("PATH")?.into_string().ok()?.split(';') {
                let candidate = Path::new(entry).join(target_path);
                if checker.is_valid(&candidate) {
                    return Some(candidate);
                }
            }
        }
        None
    }

